class Solution:
    def closestPairSum(self, nums: List[int], target: int) -> int:
        best = None
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                s = nums[i] + nums[j]
                if best is None or (abs(s - target), s) < (abs(best - target), best):
                    best = s
        return best

