class Solution {
    public int closestPairSum(int[] nums, int target) {
        long best = Long.MAX_VALUE / 4;
        for (int i = 0; i < nums.length; i++)
            for (int j = i + 1; j < nums.length; j++) {
                long s = (long) nums[i] + nums[j];
                long d = Math.abs(s - target), bd = Math.abs(best - target);
                if (d < bd || (d == bd && s < best)) best = s;
            }
        return (int) best;
    }
}

