class Solution {
    public int closestPairSum(int[] nums, int target) {
        int[] a = nums.clone();
        Arrays.sort(a);
        int i = 0, j = a.length - 1;
        long best = Long.MAX_VALUE / 4;
        while (i < j) {
            long s = (long) a[i] + a[j];
            long d = Math.abs(s - target), bd = Math.abs(best - target);
            if (d < bd || (d == bd && s < best)) best = s;
            if (s < target) i++;
            else if (s > target) j--;
            else return (int) s;
        }
        return (int) best;
    }
}

