static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

int closestPairSum(int* nums, int numsSize, int target) {
    int* a = malloc(numsSize * sizeof(int));
    memcpy(a, nums, numsSize * sizeof(int));
    qsort(a, numsSize, sizeof(int), cmp_int);
    int i = 0, j = numsSize - 1;
    long long best = LLONG_MAX / 4;
    while (i < j) {
        long long s = (long long) a[i] + a[j];
        long long d = llabs(s - target), bd = llabs(best - target);
        if (d < bd || (d == bd && s < best)) best = s;
        if (s < target) i++;
        else if (s > target) j--;
        else break;
    }
    free(a);
    return (int) best;
}
